    @php
    $actions = [];
    if ($demande->cession_parts_service || $demande->cession_parts_service == 1) {
        $actions[] = 'cession de parts';
    }

    if ($demande->address_service) {
        $actions[] = 'transfert de siège social';
    }

    if ($demande->dirigeants_service) {
        $actions[] = 'démission administrateur';
        $actions[] = 'nomination d\'administrateur';
    }
    $last = count($actions) > 1 ?array_pop($actions):'';
    $phrase = '';
    
    if (!empty($actions)) {
        $phrase = implode(', ', $actions);
        $phrase .= $last ? ' et ' . $last : '';
        $phrase = ucfirst($phrase); 
        $phrase = wordwrap($phrase, 88, '<br>', true);

    }

@endphp
@php
    $toString = function ($value) {
        if (is_array($value)) {
            $flattened = array_filter(array_map(fn($item) => is_scalar($item) ? (string) $item : '', $value));
            return implode('<br>', $flattened);
        }

        return is_scalar($value) ? (string) $value : '';
    };

    $pubText = $demande->pub_text ?? [];
    if (is_string($pubText)) {
        $pubText = ['part1' => $pubText];
    } elseif (is_array($pubText)) {
        $normalizedPubText = [];
        foreach (['part1', 'part2', 'part3', 'part4'] as $key) {
            if (array_key_exists($key, $pubText)) {
                $normalizedPubText[$key] = $toString($pubText[$key]);
            }
        }

        if (empty($normalizedPubText) && !empty($pubText)) {
            $normalizedPubText['part1'] = $toString($pubText);
        }

        $pubText = $normalizedPubText;
    } else {
        $pubText = [];
    }

    $demande->pub_text = $pubText;
@endphp
